<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/employer-functions.php';
$user = require_employer();
$id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT);
if (!$id) { http_response_code(404); exit('Candidate not found.'); }
$stmt = db()->prepare("SELECT sp.*, u.id AS candidate_user_id FROM seeker_profiles sp JOIN users u ON u.id=sp.user_id WHERE u.id=? AND u.role='seeker' AND u.status='active' AND u.onboarding_complete=1");
$stmt->execute([$id]); $candidate = $stmt->fetch();
if (!$candidate) { http_response_code(404); exit('Candidate not found.'); }
$interaction = db()->prepare('SELECT action, created_at FROM candidate_interactions WHERE employer_id=? AND seeker_user_id=?');
$interaction->execute([(int)$user['id'], $id]); $review = $interaction->fetch();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= e($candidate['full_name']) ?> — HireSwipe</title><link rel="stylesheet" href="<?= e(url('assets/css/employer.css')) ?>"></head><body class="hs-body"><header class="hs-header"><a class="hs-brand" href="<?= e(url('employer/home.php')) ?>"><span class="hs-mark">H</span><span>HireSwipe<small>Talent, without the noise.</small></span></a><nav class="hs-nav"><a href="<?= e(url('employer/home.php')) ?>">Discover</a><a href="<?= e(url('employer/search.php')) ?>">Search</a><a href="<?= e(url('employer/notifications.php')) ?>">Notifications</a><a class="signout" href="<?= e(url('auth/logout.php')) ?>">Sign out</a></nav></header><main class="profile-main"><a class="back-link" href="<?= e(url('employer/home.php')) ?>">← Back to discovery</a><section class="profile-layout"><div class="profile-portrait" style="background-image:linear-gradient(180deg,transparent 50%,rgba(8,20,29,.6)),url('<?= e(profile_photo_url($candidate['picture_path'])) ?>')"><span class="available-pill"><i></i> CANDIDATE PROFILE</span><div><h1><?= e($candidate['full_name']) ?></h1><p>⌖ <?= e($candidate['location']) ?></p></div></div><div class="profile-details"><span class="eyebrow">PROFESSIONAL SNAPSHOT</span><h2>Meet <?= e(explode(' ', trim($candidate['full_name']))[0]) ?>.</h2><div class="detail-grid"><div><small>AGE</small><strong><?= (int)$candidate['age'] ?> years</strong></div><div><small>INDUSTRY</small><strong><?= e($candidate['industries']) ?></strong></div><div><small>EMPLOYMENT TYPE</small><strong><?= e(employment_label($candidate['employment_type'])) ?></strong></div><div><small>EXPERIENCE</small><strong><?= e(number_format((float)$candidate['experience_years'], 1)) ?> years</strong></div><div><small>EXPECTED SALARY</small><strong><?= e(salary_label($candidate['expected_salary'])) ?></strong></div><div><small>QUALIFICATION</small><strong><?= e($candidate['qualification']) ?></strong></div><div><small>NATIONALITY</small><strong><?= e($candidate['nationality']) ?></strong></div></div><?php if ($candidate['cv_path'] && preg_match('~^uploads/cvs/[a-zA-Z0-9._-]+\.pdf$~', str_replace('\\','/',$candidate['cv_path']))): ?><a class="secondary-link resume-link" href="<?= e(url($candidate['cv_path'])) ?>" target="_blank" rel="noopener">View resume ↗</a><?php endif; ?><?php if ($review): ?><div class="review-note">You already reviewed this candidate: <b><?= $review['action'] === 'interest' ? 'Expressed interest' : 'Passed' ?></b>.</div><?php else: ?><div class="profile-actions"><form method="post" action="<?= e(url('actions/candidate-action.php')) ?>"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="candidate_id" value="<?= (int)$candidate['candidate_user_id'] ?>"><input type="hidden" name="action" value="rejected"><button class="round-action reject-action" type="submit" aria-label="Reject candidate"><span>×</span></button></form><span>PASS</span><form method="post" action="<?= e(url('actions/candidate-action.php')) ?>"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="candidate_id" value="<?= (int)$candidate['candidate_user_id'] ?>"><input type="hidden" name="action" value="interest"><button class="round-action interest-action" type="submit" aria-label="Express interest"><span>✓</span></button></form><span>INTERESTED</span></div><?php endif; ?></div></section></main></body></html>
